-- ─── 3.0 Project Identity & Engine ───
INSERT INTO v57.forge_nodes
  (node_key, title, phase, role, status, purpose, standalone_prompt, default_prompt, constraints, tools, skills, executor, inputs, outputs, metadata)
VALUES (
  '3.0', 'Project Identity & Engine', 'pre-production', 'standard', 'archived',
  'Fix the non-design identity of the project before any mechanic is specified: exact engine pin, render pipeline, dimension, architecture pattern, input system, test assembly prefix, save/multiplayer models (explicit N/A allowed — absence is not), the input map skeleton mechanics will reference, and per-platform performance baselines. This is the §A of the TDD and the configuration every downstream node reads.',
  'The user will describe or attach the inputs this step needs directly. Extract what they provide and proceed.',
  'From concept_data (title, platform intent, visual style) and any user-provided team/engine constraints, emit the project identity: project_name, studio, owner, genre, engine (EXACT pin), render_pipeline, dimension, pattern, input_system, test_assembly_prefix (PascalCase), save_model (or N/A), multiplayer_model (or N/A; if enabled also networking_tier/max_players/session_visibility), input_map_skeleton[] {action_map, actions[]}, performance_baselines[] {platform, resolution, fps_target, frame_budget_ms, memory_ceiling}, platform_matrix (min/recommended when PC or console), data_ownership_defaults.',
  'Engine MUST be an exact reproducible pin (e.g. ''Unity 6000.0.32f1'') — a family name alone (''Unity 6 LTS'') fails gate G-02. save_model and multiplayer_model accept explicit ''N/A'' but never absence (G-01). When multiplayer_model != N/A: networking_tier, max_players and session_visibility are required. data_ownership_defaults follow config-in/state-out guardrails and are adjusted only with written justification.',
  ARRAY[]::text[],
  ARRAY['project_identity_engine','engine_selection']::text[],
  '{"type":"llm","model":"anthropic:claude-sonnet-4-6"}'::jsonb,
  '{"wired":[{"key":"concept_data","type":"concept_data","required":true,"cardinality":"single"},{"key":"user_constraints","type":"user_constraints","required":false,"cardinality":"single"}],"direct_context":"Paste or describe the inputs this step needs, or attach a document."}'::jsonb,
  '[{"key":"project_identity","note":"Consumed by 3.2 (mechanics reference input_map_skeleton), 3.9 (dimension/pipeline coherence) and 3.12 (§A + G-01/G-02/G-14 certification). Moved here from 3.12 in v2.7.0 — it was emitted too late (after the mechanics that need it) and was orphaned.","type":"connection","label":"Project Identity","format":"project_identity","prompt":"The complete §A block: project_name, studio, owner, genre, engine (EXACT reproducible pin — never a family name), render_pipeline, dimension, pattern, input_system, test_assembly_prefix, save_model, multiplayer_model (+networking_tier/max_players/session_visibility when enabled), input_map_skeleton[], performance_baselines[], platform_matrix, data_ownership_defaults."}]'::jsonb,
  '{"preview":true,"node_type":"documentation","sub_phase":"1_documentation","amendments":[],"depends_on":[],"dna_version":"2.7.0"}'::jsonb
)
