-- ─── 3.2 Core Gameplay ───
INSERT INTO v57.forge_nodes
  (node_key, title, phase, role, status, purpose, standalone_prompt, default_prompt, constraints, tools, skills, executor, inputs, outputs, metadata)
VALUES (
  '3.2', 'Core Gameplay', 'pre-production', 'standard', 'archived',
  'Define the core loop, all mechanics with concrete rules and real numbers, win/lose conditions, difficulty curve, and the integration map between mechanics.',
  'The user will describe or attach the inputs this step needs directly. Extract what they provide and proceed.',
  'Define the core gameplay for [project] from the design pillars. Real numbers throughout; every mechanic reinforces a pillar. For each mechanic also emit the engineering-ready record (TDD §B): player_facing {goal, loop, ui_feedback, tuning_levers}; quantified rules; io {player_inputs, system_inputs, outputs as event+payload}; dependencies {kind,id}; preconditions; state_machine or N/A; components (name/type/suggested_path/events); public_api; edge_cases; and >=1 testable acceptance_criterion (EditMode/PlayMode). Emit graph_edges per mechanic for the §D dependency graph.',
  'Core loop under 15 minutes. All mechanics require real numbers — no ''high damage'', yes ''45 base damage ±20%''. Every mechanic reinforces a design pillar. Integration map required. TDD INTEGRATION (§B): every mechanic must be engineering-ready — quantified rules, inputs/outputs (events+payload), dependencies (kind+id), state machine (or N/A), component sketch, public API, edge cases, and >=1 testable acceptance criterion tagged EditMode/PlayMode. A mechanic without an acceptance criterion is incomplete.',
  ARRAY['doc_gen_docx']::text[],
  ARRAY['game_loop_design','mechanic_specification','difficulty_curve_design','real_numbers_constraint','mechanic_engineering']::text[],
  '{"type":"llm","model":"anthropic:claude-sonnet-4-6"}'::jsonb,
  '{"wired":[{"key":"design_pillars","type":"design_pillars","required":true,"cardinality":"single"},{"key":"feel_statement","type":"feel_statement","required":true,"cardinality":"single"},{"key":"concept_data","type":"concept_data","required":false,"cardinality":"single"},{"key":"project_identity","type":"project_identity","required":false,"cardinality":"single"}],"direct_context":"Paste or describe the inputs this step needs, or attach a document."}'::jsonb,
  '[{"key":"core_loop","type":"connection","uses":{"inputs":["design_pillars","feel_statement"],"siblings_if_present":[]},"label":"Core Loop","format":"core_loop","prompt":"Emit the named loop (4 steps: action / response / feedback / reward), duration under 15 min, retention hook, win/lose with fail-state consequences."},{"key":"mechanic_specs","note":"ENGINEERING-READY (TDD §B). Each mechanic_spec carries: quantified rules, io, dependencies, state_machine, components, public_api, edge_cases, >=1 testable acceptance_criterion, graph_edges, slice_scope. Still the fan-out trigger for the Prototype Specification node.","type":"connection","uses":{"inputs":["design_pillars"],"siblings_if_present":["core_loop"]},"label":"Mechanic Specs","format":"list<mechanic_spec>","prompt":"Emit all mechanics, each with concrete rules and real numbers, plus an integration map of how they affect each other. INSTANCING TRIGGER: fans out one prototype lane per mechanic at the Prototype Specification node."},{"key":"feel_statement","type":"connection","uses":{"inputs":["feel_statement"],"siblings_if_present":["mechanic_specs","core_loop"]},"label":"Feel Statement","format":"feel_statement","prompt":"Re-emit the feel statement grounded in the mechanics (level=mechanics); show how the mechanics express the pillar feel. Replaces the upstream value for all downstream nodes. ↻ consumed-and-refined."},{"key":"mechanics_engineering","note":"NEW in v2.7.0 — engineering-grade output for the TDD (3.12). PARALLEL to mechanic_specs, which remains UNTOUCHED because the GDD (3.8 §3) consumes it. R1 mitigation: two outputs, one node, zero GDD regression.","type":"connection","label":"Mechanics Engineering","format":"list<mechanic_engineering>","prompt":"One engineering-ready record per mechanic (TDD §B shape): name (PascalCase), type {feature|system|mechanic}, status/version (semver), sliceScope (bool), player_facing {goal, loop, ui_feedback (UI_* ids), tuning_levers[]}, rules[] (QUANTIFIED — concrete numbers), limits, authority, determinism, io {player_inputs[] (action names from 3.0 input_map_skeleton), system_inputs[], outputs[] (events+payload)}, persistence (none | {what,format,trigger}), dependencies[] {kind,id PascalCase — every id must resolve}, preconditions[], state_machine {states,initial,transitions} or explicit N/A, components[] (config/runtime separated), public_api, edge_cases[], acceptance_criteria[] (testable, each tagged EditMode|PlayMode, >=1), narrative_ref?, graph_edges[], companion_spec_yaml (the §C block with validationGates). Document-level: support_systems[] {id PascalCase, purpose, public_surface, spec} for every non-mechanic dependency id (→ §B-S)."},{"key":"core_gameplay_spec","type":"asset","uses":{"inputs":["design_pillars","feel_statement"],"siblings_if_present":["core_loop","mechanic_specs"]},"label":"Core Gameplay Spec","format":"docx","prompt":"Write the core gameplay spec: loop, mechanics with real numbers, difficulty curve with escalation points, integration map. Identical to the connections."}]'::jsonb,
  '{"group":"A1","status":"mandatory_in_full_preprod | mandatory_in_ideation_factory","preview":true,"node_type":"LLM","sub_phase":"1_documentation","amendments":["real_files","game_derived_skin","two_pass_qa","structure_not_skin","design_bar","examples_as_illustration"],"depends_on":["3.1"],"dna_version":"2.7.0"}'::jsonb
)
