-- ─── 3.9 Art Direction Document ───
INSERT INTO v57.forge_nodes
  (node_key, title, phase, role, status, purpose, standalone_prompt, default_prompt, constraints, tools, skills, executor, inputs, outputs, metadata)
VALUES (
  '3.9', 'Art Direction Document', 'pre-production', 'standard', 'archived',
  'Produce the complete Art Direction Document as a CANONICAL Framework 11.0 v6.0 master — authored inside the canonical section structure via the add_template_population skill (never a freeform structure; external/hand-authored ADDs receive its verbatim relocation pass first) — emit the art_bible_intake brief + the Visual Production Blueprint, segment the master into the 11 production packages (11.1–11.11) via adi_segmentation, and emit one asset_brief per production asset. Also owns the TDD-facing registries: ui_screens (§9.1, gate G-12) and scene_manifest (§13.2, gate G-13).',
  'The user will describe or attach the inputs this step needs directly. Extract what they provide and proceed.',
  'Author the ADD inside the canonical 11.0 v6.0 template (add_template_population): populate every section at its canonical number, N/A-justify what does not apply, never invent a structure. If an external ADD is provided, run the verbatim relocation pass first. Then produce the art_bible_intake connection, the ui_screens and scene_manifest registries, and the per-asset asset_briefs. Finally run adi_segmentation: Conformance Gate first (refuse + report on any mismatch), then verbatim extraction of the 11 packages and dry-run verification.',
  'CANONICAL NUMBERING IS A HARD CONSTRAINT: every section lives at its Framework 11.0 v6.0 number (the section registry embedded in add_template_population). adi_segmentation runs its CONFORMANCE GATE before ANY extraction — title↔number verification against 11.0; a mismatch refuses segmentation and emits conformance_report; N/A-with-justification passes, blanks fail; partial segmentation prohibited. Content rules: REQUIRED fields complete; conditional sections skipped = N/A justified; Core Fantasy Statement = one sentence; 3–5 Visual Pillars; Style Boundary Test on >=3 assets; §7.9 Animation Style Statement mandatory; closed color palette with role lock; asset_briefs carry the 8 production fields. Art decisions (§0.3 Shape / §0.5 Material language, style lock) are authored or approved by the art owner — drafts are flagged [DRAFT — artist approval required] and block final sign-off.',
  ARRAY['doc_gen_docx']::text[],
  ARRAY['art_direction_intake','add_template_population','adi_segmentation','art_bible_writing','style_guide_production','palette_design','v57_image_prompt_architecture','ui_scene_registry']::text[],
  '{"type":"llm","model":"anthropic:claude-sonnet-4-6"}'::jsonb,
  '{"wired":[{"key":"world_lore","type":"world_lore","required":true,"cardinality":"single"},{"key":"environments_x4","type":"environments_x4","required":true,"cardinality":"one_or_more"},{"key":"char_profiles","type":"char_profiles","required":true,"cardinality":"one_or_more"},{"key":"design_pillars","type":"design_pillars","required":true,"cardinality":"single"},{"key":"feel_statement","type":"feel_statement","required":false,"cardinality":"single"},{"key":"char_abilities","type":"char_abilities","required":false,"cardinality":"one_or_more"},{"key":"narrative_arc","type":"narrative_arc","required":false,"cardinality":"single"},{"key":"feedback_system","type":"feedback_system","required":false,"cardinality":"single"},{"key":"item_catalog","type":"item_catalog","required":false,"cardinality":"single"},{"key":"dialogue_system","type":"dialogue_system","required":false,"cardinality":"single"},{"key":"mechanics_engineering","type":"list<mechanic_engineering>","required":false,"cardinality":"single"},{"key":"project_identity","type":"project_identity","required":false,"cardinality":"single"}],"direct_context":"Paste or describe the inputs this step needs, or attach a document."}'::jsonb,
  '[{"key":"style_guide","type":"connection","uses":{"inputs":["world_lore","environments_x4","char_profiles","design_pillars"],"siblings_if_present":[]},"label":"Style Guide","format":"style_guide","prompt":"Character and environment style rules + reference rationale. Wired into VS Specification (3.13) and TDD (3.12)."},{"key":"color_palette","type":"connection","uses":{"inputs":["design_pillars","feel_statement"],"siblings_if_present":["style_guide"]},"label":"Color Palette","format":"color_palette","prompt":"Closed 4-role palette (primary/secondary/accent/danger) with hex values and use rules."},{"key":"visual_targets","type":"connection","uses":{"inputs":["feedback_system"],"siblings_if_present":["style_guide"]},"label":"Visual Targets","format":"visual_targets","prompt":"Resolution / FPS / pipeline / key VFX list. Wired into TDD (3.12)."},{"key":"art_bible_intake","note":"Structured ADI brief (Framework 11.0 v6.0). Emitted once the Art Bible is accepted; consumed by the Production-phase art nodes (11.2–11.11) which produce their own segment packages.","type":"connection","label":"Art Bible Intake","format":"art_bible_intake"},{"key":"asset_briefs","note":"One asset_brief per production asset (from the Phase 8 Asset Breakdown). The seam the Production Concept Art blueprint consumes as asset_brief_data.","type":"connection","label":"Asset Briefs","format":"list<asset_brief>"},{"key":"ui_screens","note":"NEW in v2.7.0 — required by G-12 when any mechanic references UI.","type":"connection","uses":{"inputs":["mechanics_engineering"]},"label":"Ui Screens","format":"list<ui_screen>","prompt":"One row per screen: id (UI_<Screen>, PascalCase — the ONLY way mechanics reference UI), purpose, states[], consumed_by[] (mechanic ids from mechanics_engineering, or ''standalone''). Feeds TDD §9.1 (gate G-12)."},{"key":"scene_manifest","note":"NEW in v2.7.0 — required by G-13: every PlayMode acceptance criterion must map to a scene.","type":"connection","uses":{"inputs":["mechanics_engineering"]},"label":"Scene Manifest","format":"list<scene_entry>","prompt":"One row per scene: id (SCN_<Location>_<Context>), purpose {gameplay|menu|test}, systems[] (§B/§B-S ids), slice (bool), acs_covered[] (PlayMode AC ids). Feeds TDD §13.2 (gate G-13)."},{"key":"art_direction_document","type":"asset","uses":{"inputs":["world_lore","environments_x4","char_profiles","design_pillars"],"siblings_if_present":["style_guide","color_palette","visual_targets","reference_images"]},"label":"Art Direction Document","format":"docx","prompt":"Write the full Art Bible (style guide, palette, references, character/environment rules, ability VFX, narrative visual response), with the reference images attached.","section_index":"llm_generated"},{"key":"reference_images","type":"asset","uses":{"inputs":["environments_x4","char_profiles"],"siblings_if_present":["color_palette","style_guide"]},"label":"Reference Images","format":"png","prompt":"Generate 4-6 native images covering key environments and character types, holding the locked palette.","image_gen":true},{"key":"ADI_11.1_ConceptArt","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.1 ConceptArt","format":"docx"},{"key":"visual_production_blueprint","type":"asset","label":"Visual Production Blueprint","format":"docx"},{"key":"ADI_11.2_2DVisualProduction","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.2 2DVisualProduction","format":"docx"},{"key":"ADI_11.3_3DAssetProduction","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.3 3DAssetProduction","format":"docx"},{"key":"ADI_11.4_TexturingMaterials","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.4 TexturingMaterials","format":"docx"},{"key":"ADI_11.5_RiggingSkinning","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.5 RiggingSkinning","format":"docx"},{"key":"ADI_11.6_AnimationProduction","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.6 AnimationProduction","format":"docx"},{"key":"ADI_11.7_EngineIntegration","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.7 EngineIntegration","format":"docx"},{"key":"ADI_11.8_VFXParticles","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.8 VFXParticles","format":"docx"},{"key":"ADI_11.9_AudioDirection","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.9 AudioDirection","format":"docx"},{"key":"ADI_11.10_LevelDesign","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.10 LevelDesign","format":"docx"},{"key":"ADI_11.11_MarketingArt","type":"asset","uses":{"siblings_if_present":["art_direction_document"]},"label":"ADI 11.11 MarketingArt","format":"docx"}]'::jsonb,
  '{"group":"C","status":"mandatory_in_full_preprod | removable_in_ideation_factory","preview":true,"node_type":"LLM","sub_phase":"1_documentation","amendments":["real_files","game_derived_skin","two_pass_qa","structure_not_skin","design_bar","examples_as_illustration"],"depends_on":["3.7"],"dna_version":"2.7.0"}'::jsonb
)
