  title=EXCLUDED.title, phase=EXCLUDED.phase, role=EXCLUDED.role,
  purpose=EXCLUDED.purpose, standalone_prompt=EXCLUDED.standalone_prompt, default_prompt=EXCLUDED.default_prompt,
