-- ─── 3.12 Technical Design Document ───
INSERT INTO v57.forge_nodes
  (node_key, title, phase, role, status, purpose, standalone_prompt, default_prompt, constraints, tools, skills, executor, inputs, outputs, metadata)
VALUES (
  '3.12', 'Technical Design Document', 'pre-production', 'standard', 'archived',
  'Assemble the buildable TDD (TDD_Template.md standard: §0 control+gate, §1–15, §A identity, §B per-mechanic engineering blocks, §B-S support-systems registry, §C companion spec YAML, §D dependency graph) AND reconcile it in the same pass: orphan resolution, consistency ledger, slice closure, persistence/input/UI/scene coverage. Certifies the §0.2 Completeness Gate (G-01..G-15); a failed item names the upstream node to re-run. Reconciliation is unified here (not a separate node) because 3.12 is the terminal assembler that already sees every upstream output.',
  'The user will describe or attach the inputs this step needs directly. Extract what they provide and proceed.',
  'Populate the TDD template embedded in the tdd_template_population skill from upstream inputs, then run the reconciliation pass (consistency_reconciliation skill) over the assembled document: build the §D graph from graph_edges, resolve every dependency id against §B/§B-S (orphan_report), verify slice closure (G-07), check persistence/input/UI/scene coverage (G-10..G-13), evaluate cross-system invariants (consistency_ledger, INV-*), consolidate [PENDING] markers (placeholder_registry → §15.2), and certify the §0.2 gate item by item.',
  'Single generation: tdd_complete is the ONLY generation pass. Marker policy: [PENDING owner=<node> resolve-by=<milestone>] for awaiting slots ([FORGE:*]/[PROJECTED] are DEPRECATED and fail G-08); [REQUIRED]/[RECOMMENDED]/[TO-FILL:eng] per §0.0. Engine pin must be EXACT (G-02). Every mechanic held to the same bar regardless of sliceScope. §D emitted as mermaid in the .md (canonical) PLUS an edge table (from,to,label) for PDF export — the textual edge list is what G-06/G-07 verify. A TDD whose gate does not fully PASS is a DRAFT, never published as production-ready.',
  ARRAY['doc_gen_docx']::text[],
  ARRAY['consistency_reconciliation','tdd_template_population','engine_selection','pipeline_design','feasibility_assessment']::text[],
  '{"type":"llm","model":"anthropic:claude-sonnet-4-6"}'::jsonb,
  '{"wired":[{"key":"visual_targets","type":"visual_targets","required":true,"cardinality":"single"},{"key":"core_loop","type":"core_loop","required":true,"cardinality":"single"},{"key":"mechanic_specs","type":"mechanic_spec","required":true,"cardinality":"one_or_more"},{"key":"revenue_model","type":"revenue_model","required":false,"cardinality":"single"},{"key":"audio_direction","type":"audio_direction","required":false,"cardinality":"single"},{"key":"level_map","type":"level_map","required":false,"cardinality":"single"},{"key":"feedback_system","type":"feedback_system","required":false,"cardinality":"single"},{"key":"gdd_ref","type":"gdd_ref","required":false,"cardinality":"single"},{"key":"project_identity","type":"project_identity","required":true,"cardinality":"single"},{"key":"mechanics_engineering","type":"list<mechanic_engineering>","required":true,"cardinality":"single"},{"key":"ui_screens","type":"list<ui_screen>","required":false,"cardinality":"single"},{"key":"scene_manifest","type":"list<scene_entry>","required":false,"cardinality":"single"}],"direct_context":"Paste or describe the inputs this step needs, or attach a document."}'::jsonb,
  '[{"key":"tech_stack","type":"connection","uses":{"inputs":["visual_targets","core_loop","mechanic_specs"],"siblings_if_present":[]},"label":"Tech Stack","format":"tech_stack","prompt":"Engine + version (justified), language, art pipeline, audio middleware, PC specs. Feeds Production Plan (3.14)."},{"key":"custom_systems","type":"connection","uses":{"inputs":["mechanic_specs"],"siblings_if_present":["tech_stack"]},"label":"Custom Systems","format":"custom_systems","prompt":"Each custom system with purpose/complexity/priority and a justification of why off-the-shelf fails."},{"key":"dependency_graph","note":"TDD §D — assembled from the graph_edges of every 3.2 mechanic_spec; node ids match mechanic names.","type":"connection","label":"Dependency Graph","format":"dependency_graph"},{"key":"consistency_ledger","note":"NEW v2.7.0 — reconciliation unified into 3.12.","type":"connection","label":"Consistency Ledger","format":"list<invariant>","prompt":"Cross-system invariants (INV-*): statement with concrete numbers, systems[], status {PASS|FLAG}, owner. Every FLAG must be driven to PASS (or the conflicting rule amended in 3.2) before final. → §15.3 (G-09)."},{"key":"orphan_report","type":"connection","label":"Orphan Report","format":"orphan_report","prompt":"Ids referenced in any dependencies[] or graph_edges[] that resolve to no §B mechanic and no §B-S entry. Drives 3.2 re-runs until empty (G-06)."},{"key":"slice_closure_check","type":"connection","label":"Slice Closure Check","format":"slice_closure_check","prompt":"{status: PASS|FAIL, missing[]} — the sliceScope:true subset is dependency-closed and forms an end-to-end playable loop (G-07)."},{"key":"coverage_report","type":"connection","label":"Coverage Report","format":"coverage_report","prompt":"{persistence (G-10), input (G-11), ui (G-12), scene (G-13)} — each cross-coverage result with offending items listed."},{"key":"placeholder_registry","type":"connection","label":"Placeholder Registry","format":"list<pending_item>","prompt":"Every [PENDING owner resolve-by] marker in the document: location, what, owner, resolve_by, status. → §15.2 (G-08). Empty in a final TDD."},{"key":"tdd_complete","type":"asset","uses":{"inputs":["visual_targets","core_loop","mechanic_specs"],"siblings_if_present":["tech_stack","custom_systems"]},"label":"Tdd Complete","format":"md","prompt":"Generate the TDD ONCE by populating the template embedded in the tdd_template_population skill: §0.1 document control + changelog, §0.2 gate table (certified item by item), §1–15 strategic sections, §A project identity (verbatim from 3.0), §B one block per mechanic (from mechanics_engineering), §B-S support-systems registry, §C one spec YAML per mechanic, §D mermaid graph + edge table. All markers per §0.0 policy ([PENDING owner resolve-by]; legacy [FORGE:*]/[PROJECTED] are gate failures). Markdown is the canonical artifact (mermaid is text); PDF export renders mermaid to image or uses the edge table.","section_index":"llm_generated"}]'::jsonb,
  '{"group":"C","status":"mandatory_in_full_preprod | optional_in_ideation_factory","preview":true,"node_type":"LLM","sub_phase":"1_documentation","amendments":["real_files","two_pass_qa","structure_not_skin","design_bar"],"depends_on":["3.12","3.2"],"dna_version":"2.7.0"}'::jsonb
)
ON CONFLICT (node_key) DO UPDATE SET
